//! Embedded primitive lists, catalog, and member inventory.
//!
//! Each runtime has three data files, embedded at compile time:
//!
//! - `data/primitives/<runtime>.toml`: the ambient module and its aliases, the
//!   closure sections, the classification of every standard
//!   library or builtin module as `inert` or `egress`, and the member entries.
//! - `data/catalog/<runtime>.toml`: catalogued third-party packages and their
//!   member entries.
//! - `data/inventory/<runtime>.toml`: generated by `scripts/inventory/`. It
//!   holds the standard library module list across the declared runtime range
//!   and the full member list of every module classified `egress` or on the
//!   deny list.
//!
//! An entry ID is `<language>:<module><sep><member path>`, where `<sep>` is
//! `.` for Python and JavaScript and `::` for Rust. The module part is the
//! longest declared module (a classified standard library module, a catalogued
//! package module, or the ambient module) that prefixes the path. A member path
//! segment may end in a glob: `AF_*` matches every segment starting with
//! `AF_`, and `*Command` every segment ending in `Command`; only the last
//! segment may hold one. A catalog package name may end in `/*` to cover a
//! whole npm scope (`@aws-sdk/*`).
//!
//! Lookup is longest-prefix over member paths: the entry whose member
//! path is the longest prefix of the reference wins, and at equal length an
//! exact segment beats a glob.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use serde::Deserialize;
use sha2::{Digest, Sha256};

use crate::model::{BlindSpotKind, Language, RuntimeRange};

/// One embedded data file: its repo-relative path and contents.
#[derive(Debug, Clone, Copy)]
pub struct DataFile {
    pub path: &'static str,
    pub text: &'static str,
}

macro_rules! embed {
    ($path:literal) => {
        DataFile {
            path: $path,
            text: include_str!(concat!("../../../", $path)),
        }
    };
}

/// Every data file this module embeds. Units that add data files (labels,
/// budgets, caveats, redaction, unsupported file types) append them here so
/// `data_digest` covers them.
pub const EMBEDDED: &[DataFile] = &[
    embed!("data/budgets.toml"),
    embed!("data/dependency-budgets.toml"),
    embed!("data/caveats.toml"),
    embed!("data/labels.toml"),
    embed!("data/unsupported-file-types.toml"),
    embed!("data/redaction.toml"),
    embed!("data/catalog/javascript.toml"),
    embed!("data/catalog/python.toml"),
    embed!("data/catalog/rust.toml"),
    embed!("data/inventory/javascript.toml"),
    embed!("data/inventory/python.toml"),
    embed!("data/inventory/rust.toml"),
    embed!("data/primitives/javascript.toml"),
    embed!("data/primitives/python.toml"),
    embed!("data/primitives/rust.toml"),
];

/// Separator between module and member segments in entry IDs.
pub fn separator(language: Language) -> &'static str {
    match language {
        Language::Python | Language::Javascript => ".",
        Language::Rust => "::",
    }
}

/// `sha256:<hex>` over the given files, independent of their order. Each file
/// contributes its path, a NUL byte, its length as a little-endian `u64`, and
/// its bytes, so no two distinct file sets share an input.
pub fn data_digest(files: &[(&str, &str)]) -> String {
    let mut sorted: Vec<&(&str, &str)> = files.iter().collect();
    sorted.sort_by(|a, b| a.0.cmp(b.0));
    let mut h = Sha256::new();
    for (path, text) in sorted {
        h.update(path.as_bytes());
        h.update([0u8]);
        h.update((text.len() as u64).to_le_bytes());
        h.update(text.as_bytes());
    }
    let mut out = String::from("sha256:");
    for b in h.finalize() {
        let _ = write!(out, "{b:02x}");
    }
    out
}

/// All loaded data.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Data {
    pub runtime_range: RuntimeRange,
    pub data_digest: String,
    pub python: RuntimeData,
    pub javascript: RuntimeData,
    pub rust: RuntimeData,
}

impl Data {
    /// Loads the embedded data files.
    pub fn embedded() -> Result<Data, String> {
        let files: Vec<(&str, &str)> = EMBEDDED.iter().map(|f| (f.path, f.text)).collect();
        load(&files)
    }

    pub fn runtime(&self, language: Language) -> &RuntimeData {
        match language {
            Language::Python => &self.python,
            Language::Javascript => &self.javascript,
            Language::Rust => &self.rust,
        }
    }

    pub fn runtime_mut(&mut self, language: Language) -> &mut RuntimeData {
        match language {
            Language::Python => &mut self.python,
            Language::Javascript => &mut self.javascript,
            Language::Rust => &mut self.rust,
        }
    }
}

/// The data for one runtime.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeData {
    pub language: Language,
    /// Declared range for this runtime, for example `3.8-3.13`.
    pub runtime_range: String,
    pub ambient: Ambient,
    pub closure: Closure,
    /// Standard library or builtin module classifications, sorted by name.
    pub modules: Vec<Module>,
    /// Catalogued packages, sorted by name.
    pub packages: Vec<Package>,
    /// Member entries from both files, sorted by ID.
    pub entries: Vec<Entry>,
    pub inventory: Inventory,
}

/// The runtime's global object as a module.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Ambient {
    /// `builtins` or `globalThis`; empty for Rust.
    pub module: String,
    /// Alias chains that name the ambient module, for example `["window"]` and
    /// `["document", "defaultView"]`.
    pub aliases: Vec<Vec<String>>,
    /// Ambient members that are module objects, for example JS
    /// `globalThis.process`, which is the `process` module.
    pub module_members: BTreeMap<String, String>,
}

/// Closure data sections.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Closure {
    /// Member chains that load a module named by their argument, such as
    /// `createRequire` or `module.require`. A literal argument resolves
    /// normally; anything else is a `dynamic-import` blind spot.
    pub require_equivalents: Vec<String>,
    /// Chains whose use reaches frames, globals, or constructors.
    pub introspection_roots: Vec<String>,
    /// Python attribute-name prefixes that are introspection roots.
    pub introspection_prefixes: Vec<String>,
    /// Python dunder names that are not introspection blind spots.
    pub introspection_inert: Vec<InertName>,
    /// Rust traits and types whose naming in any position is a reference.
    /// A data-guard list: the classifier does not read it. The data tests
    /// check it against the egress entries it names; an imported trait is a
    /// site through its egress entry.
    pub egress_traits: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InertName {
    pub name: String,
    pub justification: String,
    pub fixture: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ModuleClass {
    /// Wholly inert: every member is inert. Needs a justification.
    Inert,
    /// Not wholly inert: members are classified by entries and the inventory.
    Egress,
}

/// One standard library or builtin module classification.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Module {
    pub name: String,
    pub class: ModuleClass,
    pub justification: Option<String>,
}

/// One catalogued package.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Package {
    pub name: String,
    /// Module specifiers this package declares, the package name first.
    pub modules: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Origin {
    Primitives,
    Catalog,
}

/// One primitive or catalog entry.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    /// `<language>:<module><sep><members>`.
    pub id: String,
    pub module: String,
    pub members: Vec<String>,
    pub kind: EntryKind,
    /// `<language>/<category>/<case>` under `fixtures/corpus/`.
    pub fixture: String,
    pub origin: Origin,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EntryKind {
    Egress(Egress),
    BlindSpot { kind: BlindSpotKind, reason: String },
    Inert { justification: String },
}

impl EntryKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Egress(_) => "egress",
            Self::BlindSpot { .. } => "blind-spot",
            Self::Inert { .. } => "inert",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Egress {
    pub mechanism: MechanismClass,
    pub destination: Option<DestinationSpec>,
    /// Constructor-style: the call returns an object with egress
    /// methods, so the call is a site and its result is tracked one hop.
    pub constructor: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum MechanismClass {
    Network,
    Process,
    Native,
    Ipc,
}

impl MechanismClass {
    pub const ALL: [MechanismClass; 4] = [Self::Network, Self::Process, Self::Native, Self::Ipc];

    pub fn as_str(self) -> &'static str {
        match self {
            Self::Network => "network",
            Self::Process => "process",
            Self::Native => "native",
            Self::Ipc => "ipc",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|v| v.as_str() == s)
    }
}

/// Where the destination argument sits.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DestinationSpec {
    /// 1-based positional index, excluding a bound receiver.
    pub arg: Option<u32>,
    /// Python keyword or JS options-object key carrying the same value.
    pub keyword: Option<String>,
    /// For `host-port` when host and port are separate arguments: the port's
    /// 1-based positional index and its keyword or options key.
    pub port: Option<u32>,
    pub port_keyword: Option<String>,
    pub form: DestinationForm,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum DestinationForm {
    /// A URL or host.
    Url,
    /// A `(host, port)` pair or address rendered `host:port`.
    HostPort,
    /// A program, rendered `exec:<program>`.
    Program,
    /// A native library, rendered `lib:<library>`.
    Library,
    /// A local address such as a socket path.
    Address,
}

impl DestinationForm {
    pub const ALL: [DestinationForm; 5] = [
        Self::Url,
        Self::HostPort,
        Self::Program,
        Self::Library,
        Self::Address,
    ];

    pub fn as_str(self) -> &'static str {
        match self {
            Self::Url => "url",
            Self::HostPort => "host-port",
            Self::Program => "program",
            Self::Library => "library",
            Self::Address => "address",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|v| v.as_str() == s)
    }
}

/// The generated member inventory.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Inventory {
    /// Runtime versions the inventory was generated from.
    pub generated_from: Vec<String>,
    /// Versions in the declared range that were not available, with a reason.
    pub not_generated: Vec<String>,
    /// Union of standard library or builtin top-level modules over the range.
    pub stdlib_modules: Vec<String>,
    /// Module name to its full member list.
    pub members: BTreeMap<String, Vec<String>>,
}

/// What a reference classifies as.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Classification<'a> {
    /// The longest-prefix entry.
    Entry(&'a Entry),
    /// No entry matched; the reference is inside this classified module.
    Module(&'a Module),
    /// No entry matched; the reference is inside a catalogued package and
    /// matches neither its egress nor its inert patterns.
    Package(&'a Package),
}

impl RuntimeData {
    fn sep(&self) -> &'static str {
        separator(self.language)
    }

    pub fn module(&self, name: &str) -> Option<&Module> {
        self.modules
            .binary_search_by(|m| m.name.as_str().cmp(name))
            .ok()
            .map(|i| &self.modules[i])
    }

    pub fn entry(&self, id: &str) -> Option<&Entry> {
        self.entries
            .binary_search_by(|e| e.id.as_str().cmp(id))
            .ok()
            .map(|i| &self.entries[i])
    }

    /// The catalogued package declaring `specifier`, if any. A scope glob
    /// (`@aws-sdk/*`) covers every package directly under that scope.
    pub fn package_for(&self, specifier: &str) -> Option<&Package> {
        self.packages
            .iter()
            .find(|p| p.modules.iter().any(|m| module_name_matches(m, specifier)))
    }

    /// Declared module names: classified modules, catalog modules, and the
    /// ambient module.
    fn declared_modules(&self) -> impl Iterator<Item = &str> {
        self.modules
            .iter()
            .map(|m| m.name.as_str())
            .chain(
                self.packages
                    .iter()
                    .flat_map(|p| p.modules.iter().map(|s| s.as_str())),
            )
            .chain(std::iter::once(self.ambient.module.as_str()).filter(|s| !s.is_empty()))
    }

    /// Classifies `module` plus a literal member chain. The module is
    /// first extended into the longest declared submodule (`os` plus `path` is
    /// `os.path`), then entries are matched longest-prefix.
    pub fn lookup(&self, module: &str, members: &[&str]) -> Option<Classification<'_>> {
        // An ambient member that is a module object continues into that module.
        if !self.ambient.module.is_empty()
            && module == self.ambient.module
            && let Some((first, rest)) = members.split_first()
            && let Some(target) = self.ambient.module_members.get(*first)
        {
            return self.lookup(target, rest);
        }
        let sep = self.sep();
        // Extend the module into the longest declared module.
        let mut module_name = module.to_string();
        let mut rest: &[&str] = members;
        let mut candidate = module.to_string();
        for (i, m) in members.iter().enumerate() {
            candidate.push_str(sep);
            candidate.push_str(m);
            if self.declared_modules().any(|d| d == candidate) {
                module_name = candidate.clone();
                rest = &members[i + 1..];
            }
        }

        let mut best: Option<(&Entry, usize, bool)> = None;
        for e in &self.entries {
            if !module_name_matches(&e.module, &module_name) || e.members.len() > rest.len() {
                continue;
            }
            let mut exact = true;
            let ok = e.members.iter().zip(rest.iter()).all(|(pat, seg)| {
                if pat.contains('*') {
                    exact = false;
                    glob_matches(pat, seg)
                } else {
                    pat == seg
                }
            });
            if !ok {
                continue;
            }
            let better = match best {
                None => true,
                Some((_, len, ex)) => {
                    e.members.len() > len || (e.members.len() == len && exact && !ex)
                }
            };
            if better {
                best = Some((e, e.members.len(), exact));
            }
        }
        if let Some((e, _, _)) = best {
            return Some(Classification::Entry(e));
        }
        if let Some(m) = self.module(&module_name) {
            return Some(Classification::Module(m));
        }
        self.package_for(&module_name).map(Classification::Package)
    }

    /// Classifies a reference rooted at an ambient global: a bare
    /// global (`fetch`), the ambient module itself (`globalThis.fetch`), or
    /// an alias (`window.fetch`, `document.defaultView.fetch`,
    /// `__builtins__.eval`). Ambient members that are modules (JS
    /// `globalThis.process`) continue into that module.
    pub fn lookup_global(&self, chain: &[&str]) -> Option<Classification<'_>> {
        if self.ambient.module.is_empty() || chain.is_empty() {
            return None;
        }
        let rest = self.strip_ambient(chain);
        self.lookup(&self.ambient.module, rest)
    }

    /// Removes any leading ambient-module name or alias chain, repeatedly, so
    /// `window.top.fetch` and `globalThis.fetch` both reduce to `fetch`.
    fn strip_ambient<'c>(&self, mut chain: &'c [&'c str]) -> &'c [&'c str] {
        loop {
            if chain.first() == Some(&self.ambient.module.as_str()) {
                chain = &chain[1..];
                continue;
            }
            let alias = self.ambient.aliases.iter().find(|a| {
                a.len() <= chain.len() && a.iter().zip(chain.iter()).all(|(x, y)| x == y)
            });
            match alias {
                Some(a) => chain = &chain[a.len()..],
                None => return chain,
            }
        }
    }
}

/// Whether a declared module name (possibly a scope glob) covers `name`.
fn module_name_matches(declared: &str, name: &str) -> bool {
    match declared.strip_suffix("/*") {
        Some(scope) => {
            name.strip_prefix(scope)
                .and_then(|r| r.strip_prefix('/'))
                .is_some_and(|r| !r.is_empty() && !r.contains('/'))
                || declared == name
        }
        None => declared == name,
    }
}

/// Matches one segment against a pattern with at most one `*`.
fn glob_matches(pattern: &str, segment: &str) -> bool {
    match pattern.split_once('*') {
        Some((pre, post)) => {
            segment.len() >= pre.len() + post.len()
                && segment.starts_with(pre)
                && segment.ends_with(post)
        }
        None => pattern == segment,
    }
}

