struct RawPrimitives {
    language: String,
    runtime_range: String,
    #[serde(default)]
    ambient: Option<RawAmbient>,
    #[serde(default)]
    closure: Option<RawClosure>,
    #[serde(default)]
    module: Vec<RawModule>,
    #[serde(default)]
    entry: Vec<RawEntry>,
    #[serde(default)]
    inert: Vec<RawInertGroup>,
}

