fn nonempty(s: &Option<String>) -> Option<&str> {
    s.as_deref().map(str::trim).filter(|s| !s.is_empty())
}

/// Loads data from `(path, text)` pairs. The set must hold, for each runtime,
/// `data/primitives/<runtime>.toml`, `data/catalog/<runtime>.toml`, and
/// `data/inventory/<runtime>.toml`; any other file only enters the digest.
pub fn load(files: &[(&str, &str)]) -> Result<Data, String> {
    let get = |path: String| -> Result<&str, String> {
        files
            .iter()
            .find(|(p, _)| *p == path)
            .map(|(_, t)| *t)
            .ok_or_else(|| format!("{path}: missing data file"))
    };
    let mut runtimes = Vec::new();
    for lang in Language::ALL {
        let name = lang.as_str();
        let prim = format!("data/primitives/{name}.toml");
        let cat = format!("data/catalog/{name}.toml");
        let inv = format!("data/inventory/{name}.toml");
        runtimes.push(load_runtime(
            lang,
            (&prim, get(prim.clone())?),
            (&cat, get(cat.clone())?),
            (&inv, get(inv.clone())?),
        )?);
    }
    let rust = runtimes.pop().unwrap_or_else(|| unreachable!());
    let javascript = runtimes.pop().unwrap_or_else(|| unreachable!());
    let python = runtimes.pop().unwrap_or_else(|| unreachable!());
    Ok(Data {
        runtime_range: RuntimeRange {
            python: python.runtime_range.clone(),
            node: javascript.runtime_range.clone(),
            rust: rust.runtime_range.clone(),
        },
        data_digest: data_digest(files),
        python,
        javascript,
        rust,
    })
}

/// Loads one runtime from its three files.
pub fn load_runtime(
    language: Language,
    primitives: (&str, &str),
    catalog: (&str, &str),
    inventory: (&str, &str),
) -> Result<RuntimeData, String> {
    let lname = language.as_str();
    let rp: RawPrimitives =
        toml::from_str(primitives.1).map_err(|e| format!("{}: malformed: {e}", primitives.0))?;
    let rc: RawCatalog =
        toml::from_str(catalog.1).map_err(|e| format!("{}: malformed: {e}", catalog.0))?;
    let ri: RawInventory =
        toml::from_str(inventory.1).map_err(|e| format!("{}: malformed: {e}", inventory.0))?;
    for (path, l) in [
        (primitives.0, &rp.language),
        (catalog.0, &rc.language),
        (inventory.0, &ri.language),
    ] {
        if l != lname {
            return Err(format!(
                "{path}: language {l:?} where {lname:?} was expected"
            ));
        }
    }

    // Ambient module.
    let ambient = match rp.ambient {
        Some(a) => Ambient {
            aliases: a
                .aliases
                .iter()
                .map(|s| s.split('.').map(str::to_string).collect())
                .collect(),
            module: a.module,
            module_members: a.module_members,
        },
        None => Ambient::default(),
    };

    // Closure sections.
    let rcl = rp.closure.unwrap_or(RawClosure {
        require_equivalents: vec![],
        introspection_roots: vec![],
        introspection_prefixes: vec![],
        introspection_inert: vec![],
        egress_traits: vec![],
    });
    let mut introspection_inert = Vec::new();
    let mut seen_names = BTreeSet::new();
    for n in rcl.introspection_inert {
        let justification = nonempty(&n.justification)
            .ok_or_else(|| {
                format!(
                    "{}: introspection inert name {} has no justification",
                    primitives.0, n.name
                )
            })?
            .to_string();
        let fixture = nonempty(&n.fixture)
            .ok_or_else(|| {
                format!(
                    "{}: introspection inert name {} has no fixture",
                    primitives.0, n.name
                )
            })?
            .to_string();
        if !seen_names.insert(n.name.clone()) {
            return Err(format!(
                "{}: duplicate introspection inert name {}",
                primitives.0, n.name
            ));
        }
        introspection_inert.push(InertName {
            name: n.name,
            justification,
            fixture,
        });
    }
    let closure = Closure {
        require_equivalents: rcl.require_equivalents,
        introspection_roots: rcl.introspection_roots,
        introspection_prefixes: rcl.introspection_prefixes,
        introspection_inert,
        egress_traits: rcl.egress_traits,
    };

    // Module classifications.
    let mut modules: BTreeMap<String, Module> = BTreeMap::new();
    for m in rp.module {
        let class = match m.class.as_deref() {
            Some("inert") => ModuleClass::Inert,
            Some("egress") => ModuleClass::Egress,
            Some(other) => {
                return Err(format!(
                    "{}: module {}: unknown class {other:?}",
                    primitives.0, m.name
                ));
            }
            None => {
                return Err(format!(
                    "{}: module {}: missing class",
                    primitives.0, m.name
                ));
            }
        };
        if class == ModuleClass::Inert && nonempty(&m.justification).is_none() {
            return Err(format!(
                "{}: module {} is classified wholly inert without a justification",
                primitives.0, m.name
            ));
        }
        if modules.contains_key(&m.name) {
            return Err(format!(
                "{}: module {} is classified more than once",
                primitives.0, m.name
            ));
        }
        modules.insert(
            m.name.clone(),
            Module {
                name: m.name,
                class,
                justification: nonempty(&m.justification).map(str::to_string),
            },
        );
    }

    // Catalog packages.
    let mut packages: BTreeMap<String, Package> = BTreeMap::new();
    for p in rc.package {
        let mut mods = vec![p.name.clone()];
        for m in p.modules {
            if !mods.contains(&m) {
                mods.push(m);
            }
        }
        if packages.contains_key(&p.name) {
            return Err(format!("{}: duplicate package {}", catalog.0, p.name));
        }
        packages.insert(
            p.name.clone(),
            Package {
                name: p.name,
                modules: mods,
            },
        );
    }

    let mut rt = RuntimeData {
        language,
        runtime_range: rp.runtime_range,
        ambient,
        closure,
        modules: modules.into_values().collect(),
        packages: packages.into_values().collect(),
        entries: Vec::new(),
        inventory: Inventory {
            generated_from: ri.generated_from,
            not_generated: ri.not_generated,
            stdlib_modules: ri.stdlib_modules,
            members: ri.members,
        },
    };

    // Entries, with inert groups expanded into one entry per member pattern.
    let mut raw_entries: Vec<(RawEntry, Origin, &str)> = Vec::new();
    for e in rp.entry {
        raw_entries.push((e, Origin::Primitives, primitives.0));
    }
    for e in rc.entry {
        raw_entries.push((e, Origin::Catalog, catalog.0));
    }
    let sep = separator(language);
    for (groups, origin, path) in [
        (rp.inert, Origin::Primitives, primitives.0),
        (rc.inert, Origin::Catalog, catalog.0),
    ] {
        for g in groups {
            if nonempty(&g.justification).is_none() {
                return Err(format!(
                    "{path}: inert pattern group for module {} ({}) has no justification",
                    g.module,
                    g.members.join(", ")
                ));
            }
            for m in &g.members {
                raw_entries.push((
                    RawEntry {
                        id: format!("{lname}:{}{sep}{m}", g.module),
                        kind: Some("inert".into()),
                        mechanism: None,
                        destination: None,
                        constructor: false,
                        blind_spot: None,
                        reason: None,
                        justification: g.justification.clone(),
                        fixture: g.fixture.clone(),
                    },
                    origin,
                    path,
                ));
            }
        }
    }

    let mut entries: BTreeMap<String, Entry> = BTreeMap::new();
    for (e, origin, path) in raw_entries {
        let entry = build_entry(&rt, e, origin, path)?;
        if entries.contains_key(&entry.id) {
            return Err(format!("{path}: duplicate entry ID {}", entry.id));
        }
        entries.insert(entry.id.clone(), entry);
    }
    rt.entries = entries.into_values().collect();
    Ok(rt)
}

fn build_entry(rt: &RuntimeData, e: RawEntry, origin: Origin, path: &str) -> Result<Entry, String> {
    let id = e.id.clone();
    let err = |what: &str| format!("{path}: entry {id}: {what}");
    let lname = rt.language.as_str();
    let body = id
        .strip_prefix(lname)
        .and_then(|r| r.strip_prefix(':'))
        .filter(|r| !r.is_empty())
        .ok_or_else(|| err(&format!("ID must start with {lname}:")))?;
    let sep = rt.sep();

    // Longest declared module that prefixes the path.
    let module = rt
        .declared_modules()
        .filter(|m| body == *m || body.strip_prefix(*m).is_some_and(|r| r.starts_with(sep)))
        .max_by_key(|m| m.len())
        .ok_or_else(|| err("its module is not declared"))?
        .to_string();
    let rest = body.strip_prefix(&module).unwrap_or("");
    let rest = rest.strip_prefix(sep).unwrap_or(rest);
    let members: Vec<String> = if rest.is_empty() {
        Vec::new()
    } else {
        rest.split(sep).map(str::to_string).collect()
    };
    for (i, m) in members.iter().enumerate() {
        if m.is_empty() {
            return Err(err("empty member segment"));
        }
        let stars = m.matches('*').count();
        if stars > 1 || (stars == 1 && i + 1 != members.len()) {
            return Err(err("a glob is allowed only once, in the last segment"));
        }
    }

    let fixture = nonempty(&e.fixture)
        .ok_or_else(|| err("missing fixture"))?
        .to_string();
    let has_egress_fields = e.mechanism.is_some() || e.destination.is_some() || e.constructor;
    let kind = match e.kind.as_deref() {
        None => return Err(err("missing kind")),
        Some("egress") => {
            let mechanism = e
                .mechanism
                .as_deref()
                .ok_or_else(|| err("egress entry has no mechanism"))?;
            let mechanism = MechanismClass::parse(mechanism)
                .ok_or_else(|| err(&format!("unknown mechanism {mechanism:?}")))?;
            let destination = match e.destination {
                None => None,
                Some(d) => Some(DestinationSpec {
                    arg: d.arg,
                    keyword: d.keyword,
                    port: d.port,
                    port_keyword: d.port_keyword,
                    form: DestinationForm::parse(&d.form)
                        .ok_or_else(|| err(&format!("unknown destination form {:?}", d.form)))?,
                }),
            };
            EntryKind::Egress(Egress {
                mechanism,
                destination,
                constructor: e.constructor,
            })
        }
        Some("blind-spot") => {
            let k = e
                .blind_spot
                .as_deref()
                .ok_or_else(|| err("blind-spot entry has no blind_spot kind"))?;
            let kind =
                BlindSpotKind::parse(k).ok_or_else(|| err(&format!("unknown blind_spot {k:?}")))?;
            if kind.is_whole_file() {
                return Err(err(
                    "a whole-file reason cannot be an entry's blind-spot kind",
                ));
            }
            let reason = nonempty(&e.reason)
                .ok_or_else(|| err("blind-spot entry has no reason"))?
                .to_string();
            EntryKind::BlindSpot { kind, reason }
        }
        Some("inert") => {
            let justification = nonempty(&e.justification)
                .ok_or_else(|| err("inert pattern has no justification"))?
                .to_string();
            EntryKind::Inert { justification }
        }
        Some(other) => return Err(err(&format!("unknown kind {other:?}"))),
    };
    if !matches!(kind, EntryKind::Egress(_)) && has_egress_fields {
        return Err(err("only egress entries take a mechanism or destination"));
    }
    Ok(Entry {
        id,
        module,
        members,
        kind,
        fixture,
        origin,
    })
}

// ---------------------------------------------------------------------------
// Data guards. Each returns the list of violations; empty means pass.
// ---------------------------------------------------------------------------

pub mod guards {
    use super::*;
    use std::path::Path;

    /// Classifies a full path (`os.path`, `std::net`, `fs/promises`) by its
    /// first segment plus the rest, which `lookup` re-extends into the longest
    /// declared module.
    pub fn lookup_path<'a>(rt: &'a RuntimeData, path: &str) -> Option<Classification<'a>> {
        let segs: Vec<&str> = path.split(rt.sep()).collect();
        let (first, rest) = segs.split_first()?;
        rt.lookup(first, rest)
    }

    fn has_listed_ancestor(rt: &RuntimeData, listed: &BTreeSet<&str>, name: &str) -> bool {
        let sep = rt.sep();
        let mut cur = name;
        while let Some((parent, _)) = cur.rsplit_once(sep) {
            if listed.contains(parent) {
                return true;
            }
            cur = parent;
        }
        false
    }

    /// Every standard library module in the inventory list is classified, and
    /// every classified module is in that list or below a listed module.
    pub fn stdlib_classification(rt: &RuntimeData) -> Vec<String> {
        let lang = rt.language.as_str();
        let mut out = Vec::new();
        let listed: BTreeSet<&str> = rt
            .inventory
            .stdlib_modules
            .iter()
            .map(String::as_str)
            .collect();
        if listed.is_empty() {
            out.push(format!(
                "{lang}: the inventory holds no standard library module list"
            ));
        }
        for s in &listed {
            if rt.module(s).is_none() {
                out.push(format!(
                    "{lang}: standard library module {s} is in neither the inert nor the egress section"
                ));
            }
        }
        for m in &rt.modules {
            if !listed.contains(m.name.as_str()) && !has_listed_ancestor(rt, &listed, &m.name) {
                out.push(format!(
                    "{lang}: classified module {} is not in the standard library module list",
                    m.name
                ));
            }
        }
        out
    }

    fn is_inert(c: Option<Classification<'_>>) -> bool {
        match c {
            Some(Classification::Entry(e)) => matches!(e.kind, EntryKind::Inert { .. }),
            Some(Classification::Module(m)) => m.class == ModuleClass::Inert,
            _ => false,
        }
    }

    /// No deny-list module is wholly inert: neither its own classification nor
    /// any inert pattern covering its path may be inert.
    pub fn deny_list(rt: &RuntimeData, deny: &[&str]) -> Vec<String> {
        let lang = rt.language.as_str();
        let mut out = Vec::new();
        for d in deny {
            let c = lookup_path(rt, d);
            if c.is_none() {
                out.push(format!("{lang}: deny-list module {d} is not classified"));
            } else if is_inert(c) {
                out.push(format!(
                    "{lang}: deny-list module {d} is classified wholly inert"
                ));
            }
        }
        out
    }

    /// Whether the module path itself is matched by an egress or blind-spot
    /// entry, so that entry classifies every member.
    fn wholly_covered(rt: &RuntimeData, module: &str) -> bool {
        matches!(
            lookup_path(rt, module),
            Some(Classification::Entry(e)) if !matches!(e.kind, EntryKind::Inert { .. })
        )
    }

    /// Every egress-class module and every deny-list module has an inventory
    /// (unless an egress or blind-spot entry covers the whole module), and
    /// every inventory member is matched by an entry or a declared submodule.
    pub fn inventory(rt: &RuntimeData, deny: &[&str]) -> Vec<String> {
        let lang = rt.language.as_str();
        let sep = rt.sep();
        let mut out = Vec::new();
        let mut required: BTreeSet<&str> = rt
            .modules
            .iter()
            .filter(|m| m.class == ModuleClass::Egress)
            .map(|m| m.name.as_str())
            .collect();
        required.extend(deny.iter().copied());
        for r in required {
            if !rt.inventory.members.contains_key(r) && !wholly_covered(rt, r) {
                out.push(format!("{lang}: module {r} needs a member inventory"));
            }
        }
        for (module, members) in &rt.inventory.members {
            for m in members {
                let path = format!("{module}{sep}{m}");
                let ok = match lookup_path(rt, &path) {
                    Some(Classification::Entry(_)) => true,
                    Some(Classification::Module(x)) => x.name != *module,
                    _ => false,
                };
                if !ok {
                    out.push(format!(
                        "{lang}: inventory member {path} matches no egress, blind-spot, or inert pattern"
                    ));
                }
            }
        }
        out
    }

    /// Each named ID is an `egress` or `blind-spot` entry, never inert.
    pub fn not_inert(rt: &RuntimeData, ids: &[&str]) -> Vec<String> {
        let mut out = Vec::new();
        for id in ids {
            match rt.entry(id) {
                None => out.push(format!("{id}: no such entry")),
                Some(e) if matches!(e.kind, EntryKind::Inert { .. }) => {
                    out.push(format!("{id}: classified inert"))
                }
                Some(_) => {}
            }
        }
        out
    }

    /// Fixture ledger for entries whose fixture case is not authored yet
    /// (`fixtures/corpus/deferred.toml`). It must be empty at Definition of
    /// Done.
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct Deferred {
        pub cases: BTreeSet<String>,
    }

    #[derive(Deserialize)]
    #[serde(deny_unknown_fields)]
    struct RawDeferred {
        cases: Vec<String>,
    }

    pub fn parse_deferred(text: &str) -> Result<Deferred, String> {
        let raw: RawDeferred =
            toml::from_str(text).map_err(|e| format!("deferred.toml: malformed: {e}"))?;
        let mut cases = BTreeSet::new();
        for c in raw.cases {
            if !cases.insert(c.clone()) {
                return Err(format!("deferred.toml: duplicate entry {c}"));
            }
        }
        Ok(Deferred { cases })
    }

    enum Want<'a> {
        Site(&'a str),
        BlindSpot(&'a str),
        /// A `must-not-` case whose source mentions this text.
        Mention(String),
    }

    fn case_exists(corpus_root: &Path, case: &str) -> bool {
        let d = corpus_root.join(case);
        d.join("tree").is_dir() && d.join("expected.toml").is_file()
    }

    fn tree_mentions(dir: &Path, needle: &str) -> bool {
        let Ok(rd) = std::fs::read_dir(dir) else {
            return false;
        };
        let mut paths: Vec<_> = rd.flatten().map(|e| e.path()).collect();
        paths.sort();
        paths.iter().any(|p| {
            if p.is_dir() {
                tree_mentions(p, needle)
            } else {
                std::fs::read(p)
                    .map(|b| String::from_utf8_lossy(&b).contains(needle))
                    .unwrap_or(false)
            }
        })
    }

    fn labels(corpus_root: &Path, case: &str, want: &Want<'_>) -> Result<bool, String> {
        let dir = corpus_root.join(case);
        let text = std::fs::read_to_string(dir.join("expected.toml"))
            .map_err(|e| format!("{case}: cannot read expected.toml: {e}"))?;
        let v: toml::Table =
            toml::from_str(&text).map_err(|e| format!("{case}: malformed expected.toml: {e}"))?;
        let any = |table: &str, key: &str, value: &str| {
            v.get(table).and_then(|t| t.as_array()).is_some_and(|a| {
                a.iter()
                    .any(|x| x.get(key).and_then(|k| k.as_str()) == Some(value))
            })
        };
        Ok(match want {
            Want::Site(id) => any("sites", "mechanism", id),
            Want::BlindSpot(kind) => any("blind_spots", "kind", kind),
            Want::Mention(needle) => {
                case.rsplit('/')
                    .next()
                    .is_some_and(|n| n.starts_with("must-not-"))
                    && tree_mentions(&dir.join("tree"), needle)
            }
        })
    }

    fn check(
        out: &mut Vec<String>,
        corpus_root: &Path,
        deferred: &Deferred,
        what: &str,
        fixture: &str,
        want: Want<'_>,
    ) {
        if deferred.cases.contains(fixture) {
            return;
        }
        if !case_exists(corpus_root, fixture) {
            out.push(format!(
                "{what}: fixture {fixture} does not exist and is not listed in deferred.toml"
            ));
            return;
        }
        match labels(corpus_root, fixture, &want) {
            Ok(true) => {}
            Ok(false) => out.push(match want {
                Want::Site(_) => {
                    format!("{what}: fixture {fixture} labels no site with this mechanism")
                }
                Want::BlindSpot(k) => {
                    format!("{what}: fixture {fixture} labels no blind spot of kind {k}")
                }
                Want::Mention(n) => format!(
                    "{what}: fixture {fixture} is not a must-not case whose source names {n}"
                ),
            }),
            Err(e) => out.push(format!("{what}: {e}")),
        }
    }

    /// Every entry and introspection inert name names a fixture case that
    /// exists and labels it, or a case listed in the deferred ledger. An
    /// egress entry's case labels a site with the entry ID as mechanism; a
    /// blind-spot entry's case labels a blind spot of its kind; an inert
    /// entry's case is a `must-not-` case whose source names the member.
    pub fn fixtures(rt: &RuntimeData, corpus_root: &Path, deferred: &Deferred) -> Vec<String> {
        let mut out = Vec::new();
        for e in &rt.entries {
            let want = match &e.kind {
                EntryKind::Egress(_) => Want::Site(&e.id),
                EntryKind::BlindSpot { kind, .. } => Want::BlindSpot(kind.as_str()),
                EntryKind::Inert { .. } => {
                    let last = e
                        .members
                        .last()
                        .map(String::as_str)
                        .unwrap_or_else(|| e.module.rsplit(rt.sep()).next().unwrap_or(""));
                    Want::Mention(last.replace('*', ""))
                }
            };
            check(&mut out, corpus_root, deferred, &e.id, &e.fixture, want);
        }
        for n in &rt.closure.introspection_inert {
            let what = format!(
                "{} introspection inert name {}",
                rt.language.as_str(),
                n.name
            );
            check(
                &mut out,
                corpus_root,
                deferred,
                &what,
                &n.fixture,
                Want::Mention(n.name.clone()),
            );
        }
        out
    }

    /// Deferred ledger entries that no data entry names, or that now exist as
    /// cases (which must leave the ledger).
    pub fn stale_deferred(
        all: &[&RuntimeData],
        corpus_root: &Path,
        deferred: &Deferred,
    ) -> Vec<String> {
        let referenced: BTreeSet<&str> = all
            .iter()
            .flat_map(|rt| {
                rt.entries.iter().map(|e| e.fixture.as_str()).chain(
                    rt.closure
                        .introspection_inert
                        .iter()
                        .map(|n| n.fixture.as_str()),
                )
            })
            .collect();
        let mut out = Vec::new();
        for d in &deferred.cases {
            if !referenced.contains(d.as_str()) {
                out.push(format!(
                    "{d}: deferred.toml names a case no data entry uses; remove it"
                ));
            }
            if corpus_root.join(d).exists() {
                out.push(format!(
                    "{d}: deferred case now exists; remove it from deferred.toml"
                ));
            }
        }
        out
    }
}

